export function arrayStreak(p, b, s, q0, limit, end, leaf, s2) {
    // P3.6 (D044): consecutive SUCCESSFUL elements of a `[* T]` array whose
    // block already holds its one active position (|A| = 1), T one INT leaf
    // over one interval or one TEXT leaf without a regexp. Each element is
    // checked first -- items limit, head (shortest form, bytes present),
    // UTF-8, the leaf -- and only then charged, in the generic order: 5 at
    // the array (block 1 + W(|A|+1) 2 + candidate 1 + element 1), visit 1
    // [+ UTF-8 ceil(len/64)] + filter 1 + leaf 1 [+ probe 1] at the element,
    // 3 at the array (stamp, candidate, test). An element that would fail,
    // need anything else or exceed the budget stops the streak BEFORE it is
    // touched. No path write is needed: no witness can be recorded inside
    // a successful streak. Answers the next position; the element count goes
    // in s[VM_FASTM].
    const lb = p[H_S_LEAVES] + (8 * leaf);
    const kind = p[lb] & 255;
    const isint = kind === K_INT;
    const mask = p[lb + 1];
    const iv = p[H_S_INTERVALS] + (6 * p[lb + 2]);
    const lr = p[iv];
    const la = p[iv + 1];
    const lbb = p[iv + 2];
    const hr = p[iv + 3];
    const ha = p[iv + 4];
    const hb = p[iv + 5];
    const tlo = p[lb + 2];
    const thi = p[lb + 3];
    const maxit = s[O_MAX_ITEMS];
    let q = q0;
    let k = 0;
    let items = s[O_ITEMS];
    let left = s[VM_BUDGET];
    while ((k < limit) && (q < end)) {
        const ib = b[q];
        const major = (ib >>> 5) | 0;
        const ai = ib & 31;
        let hi = 0;
        let lo = ai;
        let h = 1;
        let cost = 12 - (10 * s2);
        if (items >= maxit) {
            break;
        }
        if (ai > 27) {
            break;
        }
        if (ai >= 24) {
            h = 1 + (1 << (ai - 24));
            if (h > (end - q)) {
                break;
            }
            if (ai === 24) {
                lo = b[q + 1];
            }
            if (ai === 25) {
                lo = be16(b, q + 1);
            }
            if (ai === 26) {
                lo = be32(b, q + 1);
            }
            if (ai === 27) {
                hi = be32(b, q + 1);
                lo = be32(b, q + 5);
            }
            // shortest form, else the element is not ours
            if ((ai === 24) && (lo < 24)) {
                break;
            }
            if ((ai === 25) && (lo < 256)) {
                break;
            }
            if ((ai === 26) && (((lo >>> 16) | 0) === 0)) {
                break;
            }
            if ((ai === 27) && (hi === 0)) {
                break;
            }
        }
        if (isint) {
            if (major > 1) {
                break;
            }
            if ((mask & (1 << major)) === 0) {
                break;
            }
            const rg = 3 - major;
            if (!(ptGe(rg, hi, lo, lr, la, lbb) && ptLe(rg, hi, lo, hr, ha, hb))) {
                break;
            }
            if (left < cost) {
                break;
            }
            left -= cost;
            q += h;
        } else {
            // TEXT: length, bytes present, size, UTF-8
            if (major !== 3) {
                break;
            }
            if ((hi !== 0) || (lo < 0)) {
                break;
            }
            if (lo > (end - (q + h))) {
                break;
            }
            if ((lo < tlo) || (lo > thi)) {
                break;
            }
            // schedule 2: visit + UTF-8 only
            cost = (11 - (10 * s2)) + c64(lo);
            if (left < cost) {
                break;
            }
            if (utf8InvalidAt(b, q + h, (q + h) + lo) >= 0) {
                break;
            }
            left -= cost;
            q = (q + h) + lo;
        }
        items += 1;
        k += 1;
    }
    s[VM_BUDGET] = left;
    s[O_ITEMS] = items;
    s[VM_FASTM] = k;
    if (k > 0) {
        witClear(s);
    }
    return q;
}

export function fastChild(p, pool, b, s, pos, d, cfb, ck, cw, leaf, end, ctx, ext) {
    // P3.6 (D044): eval-item on a query list of exactly ONE answer leaf
    // `leaf` without building the list: for a scalar kind on a scalar major,
    // the same profile checks, charges (consecutive charges at one offset
    // merged, which no output can tell apart) and witness rule 1, with no
    // frame or mark writes; the matched flag goes in s[VM_FASTM]. Any other
    // item (container, tag, missing byte) or leaf kind takes the generic
    // eval-item over the one-entry list written into the frame (its building
    // was charged by the caller).
    let major = -1;
    const lb = p[H_S_LEAVES] + (8 * leaf);
    const kind = p[lb] & 255;
    if (pos < end) {
        major = (b[pos] >>> 5) | 0;
    }
    // ANY, or the matching bare major, on an array or map: the generic
    // item's visit, head, container checks, filter 1, children walked dead
    // (D043), then 1 for the leaf -- directly.
    if (((major === 4) || (major === 5)) && ((kind === K_ANY) || ((kind === K_MAJOR) && (p[lb + 2] === major)))) {
        if (!charge(s, 1, pos)) {
            return -R_BUDGET;
        }
        const it0 = s[O_ITEMS] + 1;
        s[O_ITEMS] = it0;
        if (it0 > s[O_MAX_ITEMS]) {
            return fail(s, pos, CODE_TOO_MANY_ITEMS);
        }
        const ai0 = b[pos] & 31;
        let hi0 = 0;
        let lo0 = ai0;
        let q0 = pos + 1;
        if (ai0 >= 24) {
            q0 = readArg(b, s, pos, ai0, end);
            if (q0 < 0) {
                return q0;
            }
            hi0 = s[O_HI];
            lo0 = s[O_LO];
        }
        const rc = enterContainer(s, pos, q0, hi0, lo0, d, major - 4, end);
        if (rc < 0) {
            return rc;
        }
        if (!charge(s, unitOf(ctx), pos)) {
            return -R_BUDGET;
        }
        let r0;
        if (major === 4) {
            r0 = deadArrayElems(b, s, q0, lo0, d, end);
        } else {
            r0 = deadMapPairs(b, s, q0, lo0, d, end);
        }
        if (r0 < 0) {
            return r0;
        }
        if (!charge(s, unitOf(ctx), pos)) {
            return -R_BUDGET;
        }
        s[VM_FASTM] = 1;
        return r0;
    }
    if ((major < 0) || ((!scalarKind(kind)) || ((major === 4) || ((major === 5) || (major === 6))))) {
        s[cfb] = leaf;
        s[cfb + cw] = F_ANSWER;
        const rg = evalItem(p, pool, b, s, pos, d, cfb, ck, 1, end, ctx, ext);
        const fq = s[cfb + cw];
        if (rg < 0) {
            return rg;
        }
        if ((fq & F_MATCHED) !== 0) {
            s[VM_FASTM] = 1;
        } else {
            s[VM_FASTM] = 0;
        }
        return rg;
    }
    if (!charge(s, 1, pos)) {
        return -R_BUDGET;
    }
    const it = s[O_ITEMS] + 1;
    s[O_ITEMS] = it;
    if (it > s[O_MAX_ITEMS]) {
        return fail(s, pos, CODE_TOO_MANY_ITEMS);
    }
    const ai = b[pos] & 31;
    let hi = 0;
    let lo = ai;
    let q = pos + 1;
    let cs = pos + 1;
    let stop = pos + 1;
    if (ai >= 24) {
        if ((major === 7) && ((ai >= 25) && (ai <= 27))) {
            stop = scanFloat(b, s, pos, ai, end);
            if (stop < 0) {
                return stop;
            }
        } else {
            q = readArg(b, s, pos, ai, end);
            if (q < 0) {
                return q;
            }
            hi = s[O_HI];
            lo = s[O_LO];
            cs = q;
            stop = q;
        }
    }
    if (major === 2) {
        stop = takeLen(s, pos, q, hi, lo, end);
        if (stop < 0) {
            return stop;
        }
    }
    if (major === 3) {
        stop = takeLen(s, pos, q, hi, lo, end);
        if (stop < 0) {
            return stop;
        }
        if (!charge(s, c64(stop - q), pos)) {
            return -R_BUDGET;
        }
        const bad = utf8InvalidAt(b, q, stop);
        if (bad >= 0) {
            const tbad = textBad(b, s, bad, stop);
            if (tbad < 0) {
                return tbad;
            }
        }
    }
    if ((major === 7) && ((ai < 25) || (ai > 27))) {
        const r7 = scanSimple(s, pos, ai);
        if (r7 < 0) {
            return r7;
        }
    }
    const cls = itemCls(major, ai, hi, lo);
    let r = R_TYPE;
    if ((p[lb + 1] & cls) !== 0) {
        if ((kind === K_INT) && ((cls <= 2) && (p[lb + 3] === 1))) {
            // INT over one interval: filter 1 + leaf 1 + its one probe
            if (!charge(s, 1 + (2 * unitOf(ctx)), pos)) {
                return -R_BUDGET;
            }
            if (int1(p, pool, b, p[lb + 2], cls, hi, lo)) {
                r = 0;
            } else {
                r = R_RANGE;
            }
        } else if ((kind === K_TEXT) && (p[lb + 4] < 0)) {
            // TEXT without a regexp: filter 1 + leaf 1, a size check
            if (!charge(s, 2 * unitOf(ctx), pos)) {
                return -R_BUDGET;
            }
            if (((stop - cs) >= p[lb + 2]) && ((stop - cs) <= p[lb + 3])) {
                r = 0;
            } else {
                r = R_SIZE;
            }
        } else {
            if (!charge(s, 2 * unitOf(ctx), pos)) {
                return -R_BUDGET;
            }
            r = evalLeaf(p, pool, b, s, lb, kind, pos, cs, stop, cls, hi, lo);
            if (r < 0) {
                return r;
            }
        }
    } else if (!charge(s, unitOf(ctx), pos)) {
        return -R_BUDGET;
    }
    if (r === 0) {
        s[VM_FASTM] = 1;
    } else {
        s[VM_FASTM] = 0;
        if (((ctx & CTX_KEY) === 0) && witEmpty(s)) {
            if (!charge(s, 1, pos)) {
                return -R_BUDGET;
            }
            witSet(s, r, 0, d, -1, 0, pos);
        }
    }
    return stop;
}

export function evalTag(p, pool, b, s, pos, q, hi, lo, d, fb, ck, nq, end, ctx, ext) {
    // A tag item (§8.4): the scanner's depth and number checks, the filter,
    // TAG/TAGSET number tests (1 unit each), the content at depth d + 1 queried
    // with the content typesets of the leaves whose number matched (bignum and
    // typed-array content: a schema child, not an item; tag 4/40: the inner
    // array as an item; a standard-set tag: its content item, D121), the
    // scanner's tag semantics, then the leaves.
    if (d >= s[O_MAX_DEPTH]) {
        return fail(s, pos, CODE_DEPTH);
    }
    if (hi !== 0) {
        return fail(s, pos, CODE_TAG);
    }
    const big = (lo === 2) || (lo === 3);
    const tsize = typedSize(lo);
    const std = ((!big) && ((lo !== 4) && ((lo !== 40) && (tsize === 0)))) && stdAllowed(s[O_PROFILE], lo, d);
    const cr = csetRec(p, s, ck);
    const w = csetWidth(p, cr);
    const fw = csetFrame(p, cr);
    const cfb = fb + fw;
    const cck = nextCk(p, s, ck);
    const cw = csetWidth(p, csetRec(p, s, cck));
    let cls = 64;
    let cnq = 0;
    let cs = q;
    let stop;
    if ((!big) && ((lo !== 4) && ((lo !== 40) && ((tsize === 0) && (!std))))) {
        return fail(s, pos, CODE_TAG);
    }
    if (big) {
        cls = 2048;
    }
    const na = qFilterX(p, s, fb, w, nq, cls, pos, ctx);
    if (na < 0) {
        return na;
    }
    const e = newEpoch(s);
    for (let i = 0; i < nq; i++) {
        const f = qFlag(s, fb, w, i);
        const kind = qKind(p, s, fb, i);
        if (((f & F_ADMITTED) !== 0) && ((kind === K_TAG) || (kind === K_TAGSET))) {
            if (!charge(s, 1, pos)) {
                return -R_BUDGET;
            }
            const lb = qLeafBase(p, s, fb, i);
            const istag = kind === K_TAG;
            const hit = (istag && ((p[lb + 2] === 0) && (p[lb + 3] === lo))) || ((!istag) && ((cmpU64(p[lb + 2], p[lb + 3], 0, lo) <= 0) && (cmpU64(p[lb + 4], p[lb + 5], 0, lo) >= 0)));
            let cts = p[lb + 6];
            if (istag) {
                cts = p[lb + 4];
            }
            if (hit) {
                qSetFlag(s, fb, w, i, F_EVAL);
                cnq = qAdd(p, s, cfb, cw, cnq, cts, e, pos);
                if (cnq < 0) {
                    return cnq;
                }
            } else {
                qSetFlag(s, fb, w, i, R_TAG << 8);
            }
        }
    }
    if (cnq > 0) {
        pathPut(s, d + 1, P_TAG, 0);
    }
    if (big || (tsize > 0)) {
        if (!charge(s, 1, q)) {
            return -R_BUDGET;
        }
        if (big) {
            stop = deadBignum(b, s, pos, q, s[VM_BIGNUM_MAX], end);
        } else {
            stop = deadTyped(b, s, pos, q, lo, tsize, end);
        }
        if (stop < 0) {
            return stop;
        }
        cs = s[O_CSTART];
        if (cnq > 0) {
            const rb = bstrTail(p, pool, b, s, q, cs, stop, d + 1, cfb, cck, cnq, 0, ext);
            if (rb < 0) {
                return rb;
            }
        }
    } else if (std) {
        if (cnq > 0) {
            stop = evalItem(p, pool, b, s, q, d + 1, cfb, cck, cnq, end, 0, ext);
        } else {
            stop = deadItem(b, s, q, d + 1, end);
        }
        if (stop < 0) {
            return stop;
        }
        stop = deadStdCheck(b, s, pos, lo, q, stop, d);
        if (stop < 0) {
            return stop;
        }
    } else {
        const pc = pairCheck(b, s, pos, q, ifCode(lo), end);
        if (pc < 0) {
            return pc;
        }
        if (cnq > 0) {
            stop = evalItem(p, pool, b, s, q, d + 1, cfb, cck, cnq, end, 0, ext);
        } else {
            stop = deadPairBody(b, s, q, d, end);
        }
        if (stop < 0) {
            return stop;
        }
        if (lo === 4) {
            stop = decimalCheck(b, s, pos, q, stop);
        } else {
            stop = ndarrayCheck(b, s, pos, q, stop);
        }
        if (stop < 0) {
            return stop;
        }
    }
    const ec = qStamp(s, cfb, cw, cnq, pos);
    if (ec < 0) {
        return ec;
    }
    for (let j = 0; j < nq; j++) {
        const fj = qFlag(s, fb, w, j);
        if ((fj & F_EVAL) !== 0) {
            const lbj = qLeafBase(p, s, fb, j);
            let ctj = p[lbj + 4];
            if (qKind(p, s, fb, j) === K_TAGSET) {
                ctj = p[lbj + 6];
            }
            const t = tsTest(p, s, ctj, ec, pos);
            if (t < 0) {
                return t;
            }
            if (t === 1) {
                qSetFlag(s, fb, w, j, F_MATCHED);
            } else {
                qSetFlag(s, fb, w, j, R_TYPE << 8);
            }
        }
    }
    const r2 = evalScalars(p, pool, b, s, fb, w, nq, pos, cs, stop, cls, 0, lo, unitOf(ctx));
    if (r2 < 0) {
        return r2;
    }
    if (countMatched(p, s, fb, w, nq) > 0) {
        witClear(s);
    }
    const r3 = finishScalar(p, pool, b, s, fb, w, nq, d, pos, stop, ctx, ext);
    if (r3 < 0) {
        return r3;
    }
    return stop;
}

export function ifLimit(n, el) {
    if (n < 0) {
        return INF;
    }
    return n - el;
}

export function arrayStep(p, pool, b, s, pos, q, d, fb, w, area, cfb, cck, cw, fleaf, el, pend, end, s2, cx, ext) {
    // P3.6 (D044): one element of a `[* T]` array (one block, one uncounted
    // self-looping position, T one answer): the generic element step's
    // charges merged per offset -- block 1 + W(|A|+1) + candidate 1 + T's
    // element 1 at the array, the child, then stamp 1 + candidate 1 + test 1
    // -- the block's state and witness updated as array-advance would.
    // Answers the element's end (the block's alive word tells a death).
    // schedule 2 (D045): the element's bookkeeping is free
    if (!charge(s, (1 - s2) * (s[area + 2] + 4), pos)) {
        return -R_BUDGET;
    }
    pathPut(s, d + 1, P_INDEX, el);
    const rf = fastChild(p, pool, b, s, q, d + 1, cfb, cck, cw, fleaf, end, cx, ext);
    if (rf < 0) {
        return rf;
    }
    if (!charge(s, (1 - s2) * 3, pos)) {
        return -R_BUDGET;
    }
    if (s[VM_FASTM] === 1) {
        if (s[area + 2] !== 1) {
            s[area + 2] = 1;
            s[area + 3] = 1;
            s[area + 4] = 1;
        }
        witClear(s);
    } else {
        s[area + 1] = 0;
        s[area + 2] = 0;
        s[area + 3] = 0;
        s[area + 4] = 0;
        qSetFlag(s, fb, w, s[area], R_TYPE << 8);
        if (pend > 0) {
            witClear(s);
        } else if (witEmpty(s)) {
            witSet(s, R_UNEXPECTED, 0, d + 1, -1, 0, q);
        }
    }
    return rf;
}

export function arrayAlive(p, s, fb, area, nb) {
    let bo = area;
    let k = 0;
    for (let _bi = 0; _bi < nb; _bi++) {
        if (s[bo + 1] !== 0) {
            k += 1;
        }
        bo += arrayWords(p, blockAo(p, s, fb, bo));
    }
    return k;
}

export function evalArray(p, pool, b, s, pos, q0, n, d, fb, ck, nq, end, ctx, ext) {
    // An array item (§8.1) after its head and container checks: a block per
    // admitted ARRAY leaf; per element the candidate positions of the live
    // blocks give the element's query; at the end, acceptance. n < 0: a
    // VIRTUAL array (a `.cborseq` sequence, D040) whose elements are the
    // items up to end.
    const cr = csetRec(p, s, ck);
    const w = csetWidth(p, cr);
    const fw = csetFrame(p, cr);
    const area = fb + (2 * w);
    const cap = fw - (2 * w);
    const cfb = fb + fw;
    const cck = nextCk(p, s, ck);
    const cw = csetWidth(p, csetRec(p, s, cck));
    let nb = 0;
    let used = 0;
    let q = q0;
    let q1 = q0;
    let el = 0;
    let ao1 = 0;
    let fleaf = -1;
    let sleaf = -1;
    let sl = -1;
    let s2 = 0;
    let cx = 0;
    let unacc = 0;
    let nalive;
    const na = qFilterX(p, s, fb, w, nq, 16, pos, ctx);
    if (na < 0) {
        return na;
    }
    for (let i = 0; i < nq; i++) {
        if (((qFlag(s, fb, w, i) & F_ADMITTED) !== 0) && (qKind(p, s, fb, i) === K_ARRAY)) {
            const words = arrayWords(p, leafArray(p, qLeafBase(p, s, fb, i)));
            if ((used + words) > cap) {
                return -R_INCONSISTENT;
            }
            const ri = arrayBlockInit(s, area + used, i, words, pos);
            if (ri < 0) {
                return ri;
            }
            used += words;
            nb += 1;
        }
    }
    // The first block's automaton, hoisted (one block is the common case).
    if (nb > 0) {
        ao1 = blockAo(p, s, fb, area);
    }
    nalive = nb;
    // P3.6 fast step (D044): one block whose automaton is one uncounted
    // self-looping position (`[* T]`) with a one-answer typeset T.
    if (nb === 1) {
        if (((p[ao1] === 1) && (p[ao1 + 2] === 0)) && ((p[ao1 + 4] === 1) && ((p[ao1 + 8] & 1) === 1))) {
            sl = singleLeaf(p, p[ao1 + 6]);
        }
    }
    // Schedule 2 (D045 i, iii): a simple [* T] block's element steps are free
    // and a one-scalar-leaf element loses its filter and leaf units.
    if (sched2(s) && (sl >= 0)) {
        s2 = 1;
        if (scalarKind(p[p[H_S_LEAVES] + (8 * sl)] & 255)) {
            cx = CTX_SIMPLE;
        }
    }
    if ((s[VM_GENERIC] & 1) === 0) {
        fleaf = sl;
    }
    if (fleaf >= 0) {
        const lbf = p[H_S_LEAVES] + (8 * fleaf);
        const kf = p[lbf] & 255;
        if (((kf === K_INT) && (p[lbf + 3] === 1)) || ((kf === K_TEXT) && (p[lbf + 4] < 0))) {
            sleaf = fleaf;
        }
    }
    const pend = countPending(p, s, fb, w, nq);
    while (((n < 0) && (q < end)) || ((n >= 0) && (el < n))) {
        if (nalive === 0) {
            // dead elements; a run of integers in one streak (D044), never
            // element 0 of a two-element array (whose end VM_Q1 records)
            if ((el >= 1) && ((s[VM_GENERIC] & 1) === 0)) {
                const qd = deadIntStreak(b, s, q, ifLimit(n, el), end);
                const kd = s[VM_FASTM];
                if (kd > 0) {
                    q = qd;
                    el += kd - 1;
                } else {
                    q = deadItem(b, s, q, d + 1, end);
                    if (q < 0) {
                        return q;
                    }
                }
            } else {
                q = deadItem(b, s, q, d + 1, end);
                if (q < 0) {
                    return q;
                }
            }
        } else if ((sleaf >= 0) && ((el >= 1) && (s[area + 2] === 1))) {
            const qs = arrayStreak(p, b, s, q, ifLimit(n, el), end, sleaf, s2);
            const ks = s[VM_FASTM];
            if (ks > 0) {
                q = qs;
                el += ks - 1;
            } else {
                const rf2 = arrayStep(p, pool, b, s, pos, q, d, fb, w, area, cfb, cck, cw, fleaf, el, pend, end, s2, cx, ext);
                if (rf2 < 0) {
                    return rf2;
                }
                q = rf2;
                if (s[area + 1] === 0) {
                    nalive = 0;
                }
            }
        } else if (fleaf >= 0) {
            const rf = arrayStep(p, pool, b, s, pos, q, d, fb, w, area, cfb, cck, cw, fleaf, el, pend, end, s2, cx, ext);
            if (rf < 0) {
                return rf;
            }
            q = rf;
            if (s[area + 1] === 0) {
                nalive = 0;
            }
        } else {
            const e = newEpoch(s);
            let cnq = 0;
            let bo = area;
            let still = 0;
            let r;
            if (s2 === 1) {
                freeOn(s);
            }
            for (let bi = 0; bi < nb; bi++) {
                if (!charge(s, 1, pos)) {
                    return -R_BUDGET;
                }
                let ao = ao1;
                if (bi > 0) {
                    ao = blockAo(p, s, fb, bo);
                }
                if (s[bo + 1] !== 0) {
                    cnq = arrayCandidates(p, s, bo, ao, el, cfb, cw, cnq, e, pos);
                    if (cnq < 0) {
                        return cnq;
                    }
                }
                bo += arrayWords(p, ao);
            }
            freeOff(s);
            pathPut(s, d + 1, P_INDEX, el);
            if (cnq > 0) {
                r = evalItem(p, pool, b, s, q, d + 1, cfb, cck, cnq, end, cx, ext);
            } else {
                r = deadItem(b, s, q, d + 1, end);
            }
            if (r < 0) {
                return r;
            }
            if (s2 === 1) {
                freeOn(s);
            }
            const ev = qStamp(s, cfb, cw, cnq, pos);
            if (ev < 0) {
                return ev;
            }
            bo = area;
            for (let bj = 0; bj < nb; bj++) {
                let aoj = ao1;
                if (bj > 0) {
                    aoj = blockAo(p, s, fb, bo);
                }
                if (s[bo + 1] !== 0) {
                    const adv = arrayAdvance(p, s, bo, aoj, ev, pos);
                    if (adv < 0) {
                        return adv;
                    }
                    if (adv === 1) {
                        still += 1;
                    } else {
                        nalive -= 1;
                        if (adv === 2) {
                            qSetFlag(s, fb, w, s[bo], R_UNEXPECTED << 8);
                        } else {
                            qSetFlag(s, fb, w, s[bo], R_TYPE << 8);
                        }
                    }
                }
                bo += arrayWords(p, aoj);
            }
            freeOff(s);
            if ((still > 0) || (pend > 0)) {
                witClear(s);
            } else if (witEmpty(s)) {
                witSet(s, R_UNEXPECTED, 0, d + 1, -1, 0, q);
            }
            q = r;
        }
        if (el === 0) {
            q1 = q;
        }
        el += 1;
    }
    let be = area;
    for (let _bk = 0; _bk < nb; _bk++) {
        if (!charge(s, 1, pos)) {
            return -R_BUDGET;
        }
        const aok = blockAo(p, s, fb, be);
        if (s[be + 1] !== 0) {
            if (!charge(s, p[aok + 1], pos)) {
                return -R_BUDGET;
            }
            if (arrayAccepts(p, s, be, aok, el)) {
                qSetFlag(s, fb, w, s[be], F_MATCHED);
            } else {
                qSetFlag(s, fb, w, s[be], R_MISSING << 8);
                unacc += 1;
            }
        }
        be += arrayWords(p, aok);
    }
    if (n === 2) {
        s[VM_Q1] = q1;
    }
    const rs = evalScalars(p, pool, b, s, fb, w, nq, pos, q0, q, 16, 0, el, unitOf(ctx));
    if (rs < 0) {
        return rs;
    }
    const m = finishComb(p, pool, b, s, fb, w, nq, pos, q, ext);
    if (m < 0) {
        return m;
    }
    if ((m === 0) && (((ctx & CTX_KEY) === 0) && witEmpty(s))) {
        if (unacc > 0) {
            witSet(s, R_MISSING, 0, d, P_INDEX, el, pos);
        } else {
            const r1 = rule1(s, fb, w, nq, d, pos);
            if (r1 < 0) {
                return r1;
            }
        }
    }
    return q;
}

export function mapFastMode(p, mt) {
    // P3.6 (D044): 1 for a closed struct (one factor, pool and alternative,
    // the empty group), 2 for a pure table `{* K => V}` (no literal entry,
    // one absorbing group entry, K and V one leaf each), else 0.
    if ((p[mt] !== 1) || ((p[mt + 1] !== 1) || (p[mt + 2] !== 1))) {
        return 0;
    }
    const go = groupRec(p, p[mPools(p, mt) + 1]);
    const ne = p[go];
    if (ne === 0) {
        return 1;
    }
    if ((ne !== 1) || (p[mt + 3] !== 0)) {
        return 0;
    }
    if ((p[go + 4] !== 0) || (p[go + 5] !== INF)) {
        return 0;
    }
    if ((singleLeaf(p, p[go + 2]) < 0) || (singleLeaf(p, p[go + 3]) < 0)) {
        return 0;
    }
    return 2;
}

export function mapPairOk(p, s, bo, mt, kid, mode) {
    // Can this pair take the fast step? A struct: an unnamed key, or a key
    // named once whose value typeset is one leaf.
    if (mode === 2) {
        return true;
    }
    const kr = namedRec(p, s, bo, mt, kid);
    if (kr < 0) {
        return true;
    }
    const krec = mKeys(p, mt) + (4 * kr);
    if (p[krec + 3] !== 1) {
        return false;
    }
    const lit = p[(mNames(p, mt) + (2 * p[krec + 2])) + 1];
    return singleLeaf(p, p[(mLits(p, mt) + (4 * lit)) + 1]) >= 0;
}

export function mapPairFast(p, pool, b, s, pos, start, km, ps, pe, end, d, fb, w, bo, mt, cfb, cck, cw, kid, pend, mode, ps2, ext) {
    // P3.6 (D044): one pair of a single-block map in a fast mode, after the
    // shared key search and cursor step: the generic pair's charges merged
    // per offset, its pool/alternative state updates and witness. The key's
    // end goes in s[VM_FASTK]; answers the value's end.
    const pools = mPools(p, mt);
    const pso = p[pools + 4];
    const arec = mAlts(p, mt);
    const aso = p[arec + 4];
    const lits = mLits(p, mt);
    let named = false;
    let vm = 0;
    let take = false;
    let kq;
    let vq;
    if (mode === 1) {
        kq = deadItem(b, s, start, d + 1, end);
    } else {
        if (!charge(s, 1 - ps2, pos)) {
            return -R_BUDGET;
        }
        const go = groupRec(p, p[pools + 1]);
        const kl1 = singleLeaf(p, p[go + 2]);
        kq = fastChild(p, pool, b, s, start, d + 1, cfb, cck, cw, kl1, end, CTX_KEY | simpleLeaf(p, ps2, kl1), ext);
    }
    if (kq < 0) {
        return kq;
    }
    if (km <= 1) {
        if (!keyLabel(b, s, start, km)) {
            return fail(s, start, CODE_KEY_TYPE);
        }
    }
    const ko = keyOrder(b, s, ps, pe, start, kq);
    if (ko < 0) {
        return ko;
    }
    s[VM_FASTK] = kq;
    s[(bo + pso) + 2] = 0;
    if (mode === 1) {
        const kr = namedRec(p, s, bo, mt, kid);
        if (kr >= 0) {
            const krec = mKeys(p, mt) + (4 * kr);
            const lit = p[(mNames(p, mt) + (2 * p[krec + 2])) + 1];
            const lrec = lits + (4 * lit);
            named = true;
            if (!charge(s, 2 * (1 - ps2), pos)) {
                return -R_BUDGET;
            }
            pathPut(s, d + 1, P_KEY, kid);
            const vl1 = singleLeaf(p, p[lrec + 1]);
            vq = fastChild(p, pool, b, s, kq, d + 1, cfb, cck, cw, vl1, end, simpleLeaf(p, ps2, vl1), ext);
            if (vq < 0) {
                return vq;
            }
            if (!charge(s, 5 * (1 - ps2), pos)) {
                return -R_BUDGET;
            }
            if (s[VM_FASTM] === 1) {
                const li = lit - p[arec + 1];
                const wd = ((bo + aso) + 3) + (li >> 5);
                s[wd] = s[wd] | (1 << (li & 31));
                s[(bo + aso) + 2] = s[(bo + aso) + 2] + p[lrec + 2];
                s[(bo + aso) + 1] = s[(bo + aso) + 1] + 1;
                s[(bo + pso) + 2] = 1;
            } else if (p[lrec + 3] === 1) {
                s[bo + aso] = 1;
                s[(bo + pso) + 1] = s[(bo + pso) + 1] - 1;
                s[bo + 4] = s[bo + 4] - 1;
            }
        } else {
            pathPut(s, d + 1, P_ANYKEY, 0);
            vq = deadItem(b, s, kq, d + 1, end);
            if (vq < 0) {
                return vq;
            }
            if (!charge(s, 1 - ps2, pos)) {
                return -R_BUDGET;
            }
        }
    } else {
        const kmatch = s[VM_FASTM] === 1;
        const go2 = groupRec(p, p[pools + 1]);
        if (kmatch) {
            if (!charge(s, 4 * (1 - ps2), pos)) {
                return -R_BUDGET;
            }
        } else {
            if (!charge(s, 3 * (1 - ps2), pos)) {
                return -R_BUDGET;
            }
        }
        pathPut(s, d + 1, P_ANYKEY, 0);
        if (kmatch) {
            const vl2 = singleLeaf(p, p[go2 + 3]);
            vq = fastChild(p, pool, b, s, kq, d + 1, cfb, cck, cw, vl2, end, simpleLeaf(p, ps2, vl2), ext);
            if (vq < 0) {
                return vq;
            }
            vm = s[VM_FASTM];
            if (!charge(s, 4 * (1 - ps2), pos)) {
                return -R_BUDGET;
            }
        } else {
            vq = deadItem(b, s, kq, d + 1, end);
            if (vq < 0) {
                return vq;
            }
            if (!charge(s, 1 - ps2, pos)) {
                return -R_BUDGET;
            }
        }
        take = kmatch && (vm === 1);
    }
    // the pool's outcome: TAKE of the absorbing entry, or REJECT
    if (take) {
        s[(bo + pso) + 3] = 0;
    } else {
        const lv = s[(bo + pso) + 1];
        const ex = s[(bo + pso) + 2];
        s[(bo + pso) + 3] = -1;
        s[bo + pso] = s[bo + pso] + 1;
        s[bo + 4] = s[bo + 4] - (lv - ex);
        s[(bo + pso) + 1] = ex;
    }
    if (s[bo + 4] === 0) {
        s[bo + 1] = 0;
    }
    if (s[bo + 1] !== 0) {
        witClear(s);
    } else {
        if (named) {
            qSetFlag(s, fb, w, s[bo], R_VALUE << 8);
        } else {
            qSetFlag(s, fb, w, s[bo], R_UNEXPECTED << 8);
        }
        if (pend > 0) {
            witClear(s);
        } else if (witEmpty(s)) {
            if (named) {
                witSet(s, R_VALUE, 0, d + 1, -1, 0, start);
            } else {
                witSet(s, R_UNEXPECTED, 0, d + 1, -1, 0, start);
            }
        }
    }
    return vq;
}

export function preScalar(p, pool, b, s, q, end, lb, kind) {
    // P3.6 streaks: does the item at q certainly pass the profile and match
    // leaf lb -- an INT over one interval or a TEXT without a regexp?
    // Checked without charging: its end, with the units its generic
    // evaluation charges (visit, UTF-8, filter, leaf, probe) in s[O_LO]; or
    // -1 when it would not, or it is anything else.
    if (q >= end) {
        return -1;
    }
    const ib = b[q];
    const major = (ib >>> 5) | 0;
    const ai = ib & 31;
    let hi = 0;
    let lo = ai;
    let h = 1;
    if (ai > 27) {
        return -1;
    }
    if (ai >= 24) {
        h = 1 + (1 << (ai - 24));
        if (h > (end - q)) {
            return -1;
        }
        if (ai === 24) {
            lo = b[q + 1];
        }
        if (ai === 25) {
            lo = be16(b, q + 1);
        }
        if (ai === 26) {
            lo = be32(b, q + 1);
        }
        if (ai === 27) {
            hi = be32(b, q + 1);
            lo = be32(b, q + 5);
        }
        if ((ai === 24) && (lo < 24)) {
            return -1;
        }
        if ((ai === 25) && (lo < 256)) {
            return -1;
        }
        if ((ai === 26) && (((lo >>> 16) | 0) === 0)) {
            return -1;
        }
        if ((ai === 27) && (hi === 0)) {
            return -1;
        }
    }
    if (kind === K_INT) {
        if ((major > 1) || (p[lb + 3] !== 1)) {
            return -1;
        }
        if ((p[lb + 1] & (1 << major)) === 0) {
            return -1;
        }
        if (!int1(p, pool, b, p[lb + 2], major + 1, hi, lo)) {
            return -1;
        }
        s[O_LO] = 4;
        return q + h;
    }
    if ((kind === K_TEXT) && (major === 3)) {
        if ((hi !== 0) || (lo < 0)) {
            return -1;
        }
        if (lo > (end - (q + h))) {
            return -1;
        }
        if ((lo < p[lb + 2]) || (lo > p[lb + 3])) {
            return -1;
        }
        if (utf8InvalidAt(b, q + h, (q + h) + lo) >= 0) {
            return -1;
        }
        s[O_LO] = 3 + c64(lo);
        return (q + h) + lo;
    }
    return -1;
}

export function streakKind(p, leaf) {
    // Leaves pre-scalar decides: INT over one interval, TEXT without a regexp.
    if (leaf < 0) {
        return false;
    }
    const lb = p[H_S_LEAVES] + (8 * leaf);
    const kind = p[lb] & 255;
    return ((kind === K_INT) && (p[lb + 3] === 1)) || ((kind === K_TEXT) && (p[lb + 4] < 0));
}

export function mapStreak(p, pool, b, s, pos, q0, limit, end, d, bo, mt, mode, cfb, cck, cw, ps0, pe0, klo0, s2, ext) {
    // P3.6 (D044): consecutive SUCCESSFUL pairs of a single-block map in a fast
    // mode (1 struct: a named key whose value is an INT/TEXT leaf; 2 table:
    // a TEXT key leaf and an `any` or INT/TEXT value leaf). The key (text,
    // shortest head, UTF-8, ascending order, the key search done without
    // charging) and, except under `any`, the value are checked first; then
    // the pair is charged in the generic order with charges merged per
    // offset, and its state updated. A pair that would not succeed stops the
    // streak before it is touched. Answers the next position; the pair count
    // in s[VM_FASTM], the last key in s[VM_FASTP], s[VM_FASTK], the next
    // key-table bound in s[VM_FASTL].
    const pools = mPools(p, mt);
    const pso = p[pools + 4];
    const arec = mAlts(p, mt);
    const aso = p[arec + 4];
    const lits = mLits(p, mt);
    const keys = mKeys(p, mt);
    const names = mNames(p, mt);
    const nkm = p[mt + 4];
    const go = groupRec(p, p[pools + 1]);
    const maxit = s[O_MAX_ITEMS];
    let klb = 0;
    let vleaf2 = -1;
    let q = q0;
    let k = 0;
    let ps = ps0;
    let pe = pe0;
    let klo = klo0;
    if (mode === 2) {
        klb = p[H_S_LEAVES] + (8 * singleLeaf(p, p[go + 2]));
        vleaf2 = singleLeaf(p, p[go + 3]);
    }
    while ((k < limit) && (q < end)) {
        const start = q;
        const ib = b[start];
        const ai = ib & 31;
        let kh = 1;
        let kl = ai;
        let cur = s[bo + 2];
        let steps = 0;
        let lrec = 0;
        let lit = 0;
        let vend = 0;
        let vunits = 0;
        let vlf;
        // the key: text, a valid head, present, UTF-8, ascending
        if (((ib >>> 5) | 0) !== 3) {
            break;
        }
        if (ai > 27) {
            break;
        }
        if (ai >= 24) {
            kh = 1 + (1 << (ai - 24));
            if ((kh > 3) || (kh > (end - start))) {
                break;
            }
            if (ai === 24) {
                kl = b[start + 1];
            }
            if (ai === 25) {
                kl = be16(b, start + 1);
            }
            if ((ai === 24) && (kl < 24)) {
                break;
            }
            if ((ai === 25) && (kl < 256)) {
                break;
            }
        }
        if (kl > (end - (start + kh))) {
            break;
        }
        if ((s[O_ITEMS] + 2) > maxit) {
            break;
        }
        if (utf8InvalidAt(b, start + kh, (start + kh) + kl) >= 0) {
            break;
        }
        const kend = (start + kh) + kl;
        if (ps >= 0) {
            if (compareSpans(b, ps, pe, start, kend) >= 0) {
                break;
            }
        }
        const kid = keyProbe(p, pool, b, s, start, kend, klo);
        const sk = s[O_LO];
        const nlo = s[O_HI];
        if (mode === 1) {
            if (kid >= 0) {
                while ((cur < nkm) && (p[keys + (4 * cur)] < kid)) {
                    cur += 1;
                    steps += 1;
                }
            }
            if ((kid < 0) || ((cur >= nkm) || (p[keys + (4 * cur)] !== kid))) {
                break;
            }
            if (p[(keys + (4 * cur)) + 3] !== 1) {
                break;
            }
            lit = p[(names + (2 * p[(keys + (4 * cur)) + 2])) + 1];
            lrec = lits + (4 * lit);
            vlf = singleLeaf(p, p[lrec + 1]);
            if (!streakKind(p, vlf)) {
                break;
            }
        } else {
            if ((kl < p[klb + 2]) || (kl > p[klb + 3])) {
                break;
            }
            vlf = vleaf2;
        }
        // the value, unless under `any`
        const vlb = p[H_S_LEAVES] + (8 * vlf);
        const vkind = p[vlb] & 255;
        const vany = vkind === K_ANY;
        if (!vany) {
            vend = preScalar(p, pool, b, s, kend, end, vlb, vkind);
            if (vend < 0) {
                break;
            }
            vunits = s[O_LO];
        }
        // commit, in the generic order
        let ko = 0;
        let ka = (sk + 1) + steps;
        let kb = 1 + c64(kl);
        if (ps >= 0) {
            ko = c64min(pe - ps, kend - start);
        }
        if (mode === 2) {
            ka += 1;
            kb += 2;
        }
        // schedule 2 (D045): the pair costs 1 (no steps, no key element),
        // a one-leaf key or value no filter and leaf units, nothing else
        if (s2 === 1) {
            ka = sk + 1;
            if (mode === 2) {
                kb -= 2;
            }
        }
        if (!charge(s, ka, pos)) {
            return -R_BUDGET;
        }
        // the visit, then the count, then the rest: the item count is
        // observable, so no merge crosses it
        if (!charge(s, 1, start)) {
            return -R_BUDGET;
        }
        s[O_ITEMS] = s[O_ITEMS] + 1;
        if (!charge(s, (kb - 1) + ko, start)) {
            return -R_BUDGET;
        }
        if (!charge(s, (1 - s2) * (2 + (2 * (mode - 1))), pos)) {
            return -R_BUDGET;
        }
        if (vany) {
            const rv = fastChild(p, pool, b, s, kend, d + 1, cfb, cck, cw, vlf, end, simpleLeaf(p, s2, vlf), ext);
            if (rv < 0) {
                return rv;
            }
            vend = rv;
        } else {
            if (!charge(s, 1, kend)) {
                return -R_BUDGET;
            }
            s[O_ITEMS] = s[O_ITEMS] + 1;
            if (!charge(s, (vunits - 1) - (2 * s2), kend)) {
                return -R_BUDGET;
            }
        }
        if (!charge(s, (1 - s2) * (6 - mode), pos)) {
            return -R_BUDGET;
        }
        if (mode === 1) {
            const li = lit - p[arec + 1];
            const wd = ((bo + aso) + 3) + (li >> 5);
            s[bo + 2] = cur;
            s[wd] = s[wd] | (1 << (li & 31));
            s[(bo + aso) + 2] = s[(bo + aso) + 2] + p[lrec + 2];
            s[(bo + aso) + 1] = s[(bo + aso) + 1] + 1;
            s[bo + pso] = s[bo + pso] + 1;
        }
        ps = start;
        pe = kend;
        klo = nlo;
        q = vend;
        k += 1;
    }
    s[VM_FASTM] = k;
    s[VM_FASTP] = ps;
    s[VM_FASTK] = pe;
    s[VM_FASTL] = klo;
    if (k > 0) {
        witClear(s);
    }
    return q;
}

export function mapAlive(p, s, fb, area, nb) {
    let bo = area;
    let k = 0;
    for (let _bi = 0; _bi < nb; _bi++) {
        if (s[bo + 1] !== 0) {
            k += 1;
        }
        bo += p[blockMt(p, s, fb, bo) + 6];
    }
    return k;
}

export function evalMap(p, pool, b, s, pos, q0, n, d, fb, ck, nq, end, ctx, ext) {
    // A map item (§8.3) after its head and container checks. Per pair: the
    // scanner's key checks; the key search, cursors, the key's query (key
    // typesets of live residual pools), the key, its order; the key phase
    // (candidates); the value with the candidates' value typesets; the
    // update. At the end, satisfaction, then witness rules 3/4/1.
    const cr = csetRec(p, s, ck);
    const w = csetWidth(p, cr);
    const fw = csetFrame(p, cr);
    const area = fb + (2 * w);
    const cap = fw - (2 * w);
    const cfb = fb + fw;
    const cck = nextCk(p, s, ck);
    const cw = csetWidth(p, csetRec(p, s, cck));
    const cose = (d === 0) && (s[O_COSE] !== 0);
    let nb = 0;
    let used = 0;
    let ccap = 0;
    let q = q0;
    let ps = -1;
    let pe = -1;
    let klo = 0;
    let fmode = 0;
    let smap = 0;
    let smode = 0;
    let pk = 0;
    let unsat = 0;
    let nalive;
    const na = qFilterX(p, s, fb, w, nq, 32, pos, ctx);
    if (na < 0) {
        return na;
    }
    for (let i = 0; i < nq; i++) {
        if (((qFlag(s, fb, w, i) & F_ADMITTED) !== 0) && (qKind(p, s, fb, i) === K_MAP)) {
            const mt = leafMap(p, qLeafBase(p, s, fb, i));
            const sw = p[mt + 6];
            if ((used + sw) > cap) {
                return -R_INCONSISTENT;
            }
            const ri = mapBlockInit(p, s, area + used, i, mt, pos);
            if (ri < 0) {
                return ri;
            }
            used += sw;
            ccap += p[mt + 7];
            nb += 1;
        }
    }
    if ((used + (4 * ccap)) > cap) {
        return -R_INCONSISTENT;
    }
    nalive = nb;
    if (nb === 1) {
        smap = mapFastMode(p, blockMt(p, s, fb, area));
    }
    if ((s[VM_GENERIC] & 1) === 0) {
        fmode = smap;
    }
    if (fmode === 1) {
        smode = 1;
    }
    if (fmode === 2) {
        const gom = groupRec(p, p[mPools(p, blockMt(p, s, fb, area)) + 1]);
        const kfl = singleLeaf(p, p[gom + 2]);
        const vfl = singleLeaf(p, p[gom + 3]);
        const klbm = p[H_S_LEAVES] + (8 * kfl);
        if ((((p[klbm] & 255) === K_TEXT) && (p[klbm + 4] < 0)) && (((p[p[H_S_LEAVES] + (8 * vfl)] & 255) === K_ANY) || streakKind(p, vfl))) {
            smode = 2;
        }
    }
    const cl = area + used;
    const pend = countPending(p, s, fb, w, nq);
    while (pk < n) {
        if ((smode > 0) && (nalive > 0)) {
            const qm = mapStreak(p, pool, b, s, pos, q, n - pk, end, d, area, blockMt(p, s, fb, area), smode, cfb, cck, cw, ps, pe, klo, ifS2(s), ext);
            const km2 = s[VM_FASTM];
            if (qm < 0) {
                return qm;
            }
            if (km2 > 0) {
                q = qm;
                ps = s[VM_FASTP];
                pe = s[VM_FASTK];
                klo = s[VM_FASTL];
                pk += km2;
            }
        }
        if (pk < n) {
            const start = q;
            if (start >= end) {
                return fail(s, start, CODE_TRUNCATED);
            }
            const km = (b[start] >>> 5) | 0;
            if (km !== 3) {
                if (!keyPeek(s, km, cose)) {
                    return fail(s, start, CODE_KEY_TYPE);
                }
            }
            if (nalive === 0) {
                q = deadItem(b, s, start, d + 1, end);
                if (q < 0) {
                    return q;
                }
                if (km <= 1) {
                    if (!keyLabel(b, s, start, km)) {
                        return fail(s, start, CODE_KEY_TYPE);
                    }
                }
                const kod = keyOrder(b, s, ps, pe, start, q);
                if (kod < 0) {
                    return kod;
                }
                ps = start;
                pe = q;
                q = deadItem(b, s, q, d + 1, end);
                if (q < 0) {
                    return q;
                }
            } else {
                const ke = keySpanEnd(b, start, end);
                let kid = -1;
                let cnq = 0;
                let nc = 0;
                let named = false;
                let vnq = 0;
                let ps2 = 0;
                let still = 0;
                let kq;
                let vq;
                let bo;
                // The key's id in the schema-wide key table.
                if (ke > start) {
                    kid = keySearch(p, pool, b, s, start, ke, klo, pos);
                    if (kid === (-2)) {
                        return -R_BUDGET;
                    }
                    klo = s[O_HI];
                }
                // Cursors: 1 unit per block, 1 per cursor step (a fast-mode map
                // here; otherwise fused with the key query below: charges at
                // one offset with no check between may be reordered).
                if (smap > 0) {
                    // the cursor first, uncharged, to decide schedule 2's simple
                    // pair (D045 ii); then block 1 + steps, or the pair's 1 unit,
                    // merged at the map's offset
                    const c0 = s[area + 2];
                    const mt0 = blockMt(p, s, fb, area);
                    freeOn(s);
                    mapCursor(p, s, area, mt0, kid, pos);
                    freeOff(s);
                    if (sched2(s) && mapPairOk(p, s, area, mt0, kid, smap)) {
                        ps2 = 1;
                        if (!charge(s, 1, pos)) {
                            return -R_BUDGET;
                        }
                    } else if (!charge(s, 1 + (s[area + 2] - c0), pos)) {
                        return -R_BUDGET;
                    }
                }
                if ((fmode > 0) && mapPairOk(p, s, area, blockMt(p, s, fb, area), kid, fmode)) {
                    const vf = mapPairFast(p, pool, b, s, pos, start, km, ps, pe, end, d, fb, w, area, blockMt(p, s, fb, area), cfb, cck, cw, kid, pend, fmode, ps2, ext);
                    if (vf < 0) {
                        return vf;
                    }
                    ps = start;
                    pe = s[VM_FASTK];
                    if (s[area + 1] === 0) {
                        nalive = 0;
                    }
                    q = vf;
                } else {
                    // The key, queried with the live residual key typesets.
                    if (ps2 === 1) {
                        freeOn(s);
                    }
                    const e = newEpoch(s);
                    bo = area;
                    for (let _bj = 0; _bj < nb; _bj++) {
                        const mtj = blockMt(p, s, fb, bo);
                        if (smap === 0) {
                            if (!charge(s, 1, pos)) {
                                return -R_BUDGET;
                            }
                            if (s[bo + 1] !== 0) {
                                const rc2 = mapCursor(p, s, bo, mtj, kid, pos);
                                if (rc2 < 0) {
                                    return rc2;
                                }
                            }
                        }
                        if (s[bo + 1] !== 0) {
                            cnq = mapKeyQuery(p, s, bo, mtj, cfb, cw, cnq, e, pos);
                            if (cnq < 0) {
                                return cnq;
                            }
                        }
                        bo += p[mtj + 6];
                    }
                    freeOff(s);
                    if (cnq > 0) {
                        kq = evalItem(p, pool, b, s, start, d + 1, cfb, cck, cnq, end, CTX_KEY | simpleOf(p, s, ps2, cfb, cnq), ext);
                    } else {
                        kq = deadItem(b, s, start, d + 1, end);
                    }
                    if (kq < 0) {
                        return kq;
                    }
                    if (km <= 1) {
                        if (!keyLabel(b, s, start, km)) {
                            return fail(s, start, CODE_KEY_TYPE);
                        }
                    }
                    const ko = keyOrder(b, s, ps, pe, start, kq);
                    if (ko < 0) {
                        return ko;
                    }
                    ps = start;
                    pe = kq;
                    // Key phase: candidates.
                    if (ps2 === 1) {
                        freeOn(s);
                    }
                    const ek = qStamp(s, cfb, cw, cnq, pos);
                    if (ek < 0) {
                        return ek;
                    }
                    bo = area;
                    for (let _bk = 0; _bk < nb; _bk++) {
                        const mtk = blockMt(p, s, fb, bo);
                        if (s[bo + 1] !== 0) {
                            if (simpleStruct(p, mtk)) {
                                nc = keyPhaseStruct(p, s, bo, mtk, kid, cl, nc, ccap, pos);
                            } else {
                                nc = mapKeyPhase(p, s, bo, mtk, kid, ek, cl, nc, ccap, pos);
                            }
                            if (nc < 0) {
                                return nc;
                            }
                        }
                        bo += p[mtk + 6];
                    }
                    for (let c = 0; c < nc; c++) {
                        if ((s[(cl + (4 * c)) + 1] & 1) === 0) {
                            named = true;
                        }
                    }
                    if (named) {
                        pathPut(s, d + 1, P_KEY, kid);
                    } else {
                        pathPut(s, d + 1, P_ANYKEY, 0);
                    }
                    // The value, queried with the candidates' value typesets.
                    const e2 = newEpoch(s);
                    for (let c2 = 0; c2 < nc; c2++) {
                        const vts = candVts(p, s, fb, cl, c2);
                        vnq = qAdd(p, s, cfb, cw, vnq, vts, e2, pos);
                        if (vnq < 0) {
                            return vnq;
                        }
                    }
                    freeOff(s);
                    if (vnq > 0) {
                        vq = evalItem(p, pool, b, s, kq, d + 1, cfb, cck, vnq, end, simpleOf(p, s, ps2, cfb, vnq), ext);
                    } else {
                        vq = deadItem(b, s, kq, d + 1, end);
                    }
                    if (vq < 0) {
                        return vq;
                    }
                    if (ps2 === 1) {
                        freeOn(s);
                    }
                    // Update: each candidate (1 unit + its value test), then
                    // each alive block.
                    const ev = qStamp(s, cfb, cw, vnq, pos);
                    if (ev < 0) {
                        return ev;
                    }
                    bo = area;
                    for (let _bl = 0; _bl < nb; _bl++) {
                        const mtl = blockMt(p, s, fb, bo);
                        if (s[bo + 1] !== 0) {
                            // this block's candidates (contiguous), 1 unit + its
                            // value test each, then its update
                            let c3 = s[bo + 3];
                            while ((c3 < nc) && (s[cl + (4 * c3)] === bo)) {
                                if (!charge(s, 1, pos)) {
                                    return -R_BUDGET;
                                }
                                const vts3 = candVtsMt(p, s, mtl, cl, c3);
                                const t = tsTest(p, s, vts3, ev, pos);
                                if (t < 0) {
                                    return t;
                                }
                                if (t === 1) {
                                    const kw = (cl + (4 * c3)) + 1;
                                    s[kw] = s[kw] | 2;
                                }
                                c3 += 1;
                            }
                            const ss = simpleStruct(p, mtl);
                            let u;
                            if (ss) {
                                u = updateStruct(p, s, bo, mtl, kid, cl, nc, pos);
                            } else {
                                u = mapUpdate(p, s, bo, mtl, kid, cl, nc, pos);
                            }
                            if (u < 0) {
                                return u;
                            }
                            if (u === 1) {
                                still += 1;
                            } else {
                                nalive -= 1;
                                if (blockNamed(s, bo, cl, nc)) {
                                    qSetFlag(s, fb, w, s[bo], R_VALUE << 8);
                                } else {
                                    qSetFlag(s, fb, w, s[bo], R_UNEXPECTED << 8);
                                }
                            }
                        }
                        bo += p[mtl + 6];
                    }
                    freeOff(s);
                    if ((still > 0) || (pend > 0)) {
                        witClear(s);
                    } else if (witEmpty(s)) {
                        if (named) {
                            witSet(s, R_VALUE, 0, d + 1, -1, 0, start);
                        } else {
                            witSet(s, R_UNEXPECTED, 0, d + 1, -1, 0, start);
                        }
                    }
                    q = vq;
                }
            }
        }
        pk += 1;
    }
    // The end: 1 unit per block; alive blocks + 1 per alternative and pool.
    let be = area;
    let best = -1;
    let bestbo = 0;
    for (let _bm = 0; _bm < nb; _bm++) {
        if (!charge(s, 1, pos)) {
            return -R_BUDGET;
        }
        const mtm = blockMt(p, s, fb, be);
        if (s[be + 1] !== 0) {
            if (!charge(s, p[mtm + 2] + p[mtm + 1], pos)) {
                return -R_BUDGET;
            }
            if (mapSatisfied(p, s, be, mtm)) {
                qSetFlag(s, fb, w, s[be], F_MATCHED);
            } else {
                qSetFlag(s, fb, w, s[be], R_MISSING << 8);
                unsat += 1;
                const lid = s[fb + s[be]];
                if ((best < 0) || (lid < best)) {
                    best = lid;
                    bestbo = be;
                }
            }
        }
        be += p[mtm + 6];
    }
    const rs = evalScalars(p, pool, b, s, fb, w, nq, pos, q0, q, 32, 0, n, unitOf(ctx));
    if (rs < 0) {
        return rs;
    }
    const m = finishComb(p, pool, b, s, fb, w, nq, pos, q, ext);
    if (m < 0) {
        return m;
    }
    if ((m === 0) && (((ctx & CTX_KEY) === 0) && witEmpty(s))) {
        if (unsat > 0) {
            const mtb = blockMt(p, s, fb, bestbo);
            const r4 = mapMissing(p, s, bestbo, mtb, d, pos);
            if (r4 < 0) {
                return r4;
            }
        } else {
            const r1 = rule1(s, fb, w, nq, d, pos);
            if (r1 < 0) {
                return r1;
            }
        }
    }
    return q;
}

export function evalItem(p, pool, b, s, pos, d, fb, ck, nq, end, ctx, ext) {
    // One LIVE item at pos, physical depth d, query list (nq > 0 entries) in the
    // frame at fb: visit (1 unit), counted, then its head -- the scanner's
    // `item`, with the schema evaluated alongside.
    if (!charge(s, 1, pos)) {
        return -R_BUDGET;
    }
    const it = s[O_ITEMS] + 1;
    s[O_ITEMS] = it;
    if (it > s[O_MAX_ITEMS]) {
        return fail(s, pos, CODE_TOO_MANY_ITEMS);
    }
    if (pos >= end) {
        return fail(s, pos, CODE_TRUNCATED);
    }
    const ib = b[pos];
    const major = (ib >>> 5) | 0;
    const ai = ib & 31;
    const cr = csetRec(p, s, ck);
    const w = csetWidth(p, cr);
    let hi = 0;
    let lo = ai;
    let q = pos + 1;
    let stop;
    if (cr < 0) {
        return -R_INCONSISTENT;
    }
    if (ai >= 24) {
        if (major === 7) {
            if ((ai >= 25) && (ai <= 27)) {
                stop = scanFloat(b, s, pos, ai, end);
                if (stop < 0) {
                    return stop;
                }
                const nf = qFilterX(p, s, fb, w, nq, itemCls(7, ai, 0, 0), pos, ctx);
                if (nf < 0) {
                    return nf;
                }
                const rf = evalScalars(p, pool, b, s, fb, w, nq, pos, pos + 1, stop, itemCls(7, ai, 0, 0), 0, 0, unitOf(ctx));
                if (rf < 0) {
                    return rf;
                }
                const ff = finishScalar(p, pool, b, s, fb, w, nq, d, pos, stop, ctx, ext);
                if (ff < 0) {
                    return ff;
                }
                return stop;
            }
        }
        q = readArg(b, s, pos, ai, end);
        if (q < 0) {
            return q;
        }
        hi = s[O_HI];
        lo = s[O_LO];
    }
    if (major === 4) {
        const ra = enterContainer(s, pos, q, hi, lo, d, 0, end);
        if (ra < 0) {
            return ra;
        }
        return evalArray(p, pool, b, s, pos, q, lo, d, fb, ck, nq, end, ctx, ext);
    }
    if (major === 5) {
        const rm = enterContainer(s, pos, q, hi, lo, d, 1, end);
        if (rm < 0) {
            return rm;
        }
        return evalMap(p, pool, b, s, pos, q, lo, d, fb, ck, nq, end, ctx, ext);
    }
    if (major === 6) {
        return evalTag(p, pool, b, s, pos, q, hi, lo, d, fb, ck, nq, end, ctx, ext);
    }
    stop = q;
    if (major === 2) {
        stop = takeLen(s, pos, q, hi, lo, end);
        if (stop < 0) {
            return stop;
        }
        const rb = bstrTail(p, pool, b, s, pos, q, stop, d, fb, ck, nq, ctx, ext);
        if (rb < 0) {
            return rb;
        }
        return stop;
    }
    if (major === 3) {
        stop = takeLen(s, pos, q, hi, lo, end);
        if (stop < 0) {
            return stop;
        }
        if (!charge(s, c64(stop - q), pos)) {
            return -R_BUDGET;
        }
        const bad = utf8InvalidAt(b, q, stop);
        if (bad >= 0) {
            const tbad2 = textBad(b, s, bad, stop);
            if (tbad2 < 0) {
                return tbad2;
            }
        }
    }
    if (major === 7) {
        const r7 = scanSimple(s, pos, ai);
        if (r7 < 0) {
            return r7;
        }
    }
    const cls = itemCls(major, ai, hi, lo);
    const nf2 = qFilterX(p, s, fb, w, nq, cls, pos, ctx);
    if (nf2 < 0) {
        return nf2;
    }
    const r2 = evalScalars(p, pool, b, s, fb, w, nq, pos, q, stop, cls, hi, lo, unitOf(ctx));
    if (r2 < 0) {
        return r2;
    }
    const f2 = finishScalar(p, pool, b, s, fb, w, nq, d, pos, stop, ctx, ext);
    if (f2 < 0) {
        return f2;
    }
    return stop;
}
